() => {
  const select = document.querySelector('#type-filter');
  select.value = '仙侠';
  select.dispatchEvent(new Event('change', { bubbles: true }));
  if (!document.querySelector('#recommend-empty').textContent.includes('暂无仙侠推荐')) throw new Error('Missing honest type empty state');
  select.value = '全部类型';
  select.dispatchEvent(new Event('change', { bubbles: true }));
  return { typeEmptyState: true, restored: true };
}

() => {
  const storageBefore = localStorage.getItem('issue-100-prototype-books');
  const scenario = document.querySelector('#scenario');
  const expected = { loading: '加载中', empty: '读取成功', stale: '已过期', partial: '部分来源失败', 'failed-cache': '显示最后成功缓存', 'failed-none': '没有可用缓存', ok: '2个官方组织' };
  const observed = [];
  for (const [value, text] of Object.entries(expected)) {
    scenario.value = value;
    scenario.dispatchEvent(new Event('change', { bubbles: true }));
    if (!document.querySelector('#catalogue-status').textContent.includes(text)) throw new Error(`Status missing: ${value}`);
    const count = document.querySelectorAll('#recommend-list article').length;
    if (count !== (['loading', 'empty', 'failed-none'].includes(value) ? 0 : 6)) throw new Error(`Wrong records for ${value}`);
    observed.push({ value, count });
  }
  if (localStorage.getItem('issue-100-prototype-books') !== storageBefore) throw new Error('Scenario changed private list');
  return { observed, privateStorageUnchanged: true, note: 'UI scenario checks, not collector/backend proof' };
}

() => {
  const select = document.querySelector('#edit-types');
  for (const option of select.options) option.selected = option.value === '仙侠' || option.value === '古典文学';
  select.dispatchEvent(new Event('change', { bubbles: true }));
  return { selected: [...select.selectedOptions].map((option) => option.value) };
}

() => {
  const books = JSON.parse(localStorage.getItem('issue-100-prototype-books'));
  const book = books.find((entry) => entry.title === '梅西传');
  if (!book || book.bookInfo.summary !== '这是我自己写的简介。' || !book.bookInfo.types.includes('仙侠')) throw new Error('Metadata did not persist');
  if (book.read !== false) throw new Error('Edit changed read state');
  return { summarySaved: true, types: book.bookInfo.types, read: book.read };
}

() => {
  const clickNamed = (name) => {
    const button = [...document.querySelectorAll('#book-list button')].find((node) => node.getAttribute('aria-label') === name || node.textContent === name);
    if (!button) throw new Error(`Missing ${name}`);
    button.click();
  };
  const before = localStorage.getItem('issue-100-prototype-books');
  clickNamed('查看《同名示例》补全建议');
  if (document.querySelectorAll('#book-list .candidate').length !== 2) throw new Error('Ambiguous candidates missing');
  if (localStorage.getItem('issue-100-prototype-books') !== before) throw new Error('View silently saved candidate');
  clickNamed('关闭建议');
  if (localStorage.getItem('issue-100-prototype-books') !== before) throw new Error('Reject candidate wrote storage');
  clickNamed('查看《旧书示例》补全建议');
  if (!document.querySelector('#book-list').textContent.includes('没有匹配候选')) throw new Error('No match state missing');
  clickNamed('关闭建议');
  clickNamed('查看《梅西传》补全建议');
  clickNamed('确认采用[阿根廷] 塞尔吉奥·莱文斯基的候选');
  const books = JSON.parse(localStorage.getItem('issue-100-prototype-books'));
  const book = books.find((entry) => entry.title === '梅西传');
  if (book.bookInfo.summary !== '这是我自己写的简介。' || !book.bookInfo.types.includes('仙侠')) throw new Error('Candidate overwrote manual information');
  const adoptedBefore = localStorage.getItem('issue-100-prototype-books');
  clickNamed('查看《梅西传》补全建议');
  clickNamed('确认采用[阿根廷] 塞尔吉奥·莱文斯基的候选');
  if (localStorage.getItem('issue-100-prototype-books') !== adoptedBefore) throw new Error('No gaps should be no-op');
  clickNamed('关闭建议');
  return { ambiguous: 2, viewAndRejectNoWrite: true, noMatch: true, manualPreserved: true, noGapsNoWrite: true };
}

() => {
  const page = document.documentElement;
  if (page.scrollWidth > window.innerWidth + 1) throw new Error(`Horizontal overflow: ${page.scrollWidth}/${window.innerWidth}`);
  const hiddenParents = (node) => node.closest('[hidden]') || node.getClientRects().length === 0;
  const controls = [...document.querySelectorAll('button, input, textarea, select, a')].filter((node) => !hiddenParents(node));
  for (const control of controls) {
    const bounds = control.getBoundingClientRect();
    if (bounds.left < -1 || bounds.right > window.innerWidth + 1) throw new Error(`Control outside viewport: ${control.textContent}`);
    if (control.tagName === 'BUTTON' && bounds.height < 43) throw new Error('Button touch target too short');
  }
  return { width: window.innerWidth, scrollWidth: page.scrollWidth, visibleControls: controls.length, noOverflow: true };
}
